import{a as e,i as t,r as n,t as r}from"./app-DUb33vxN.js";var i=JSON.parse(`{"path":"/%E7%AC%AC22%E7%AB%A0%20%E7%BB%84%E7%BB%87%E9%80%9A%E7%94%A8%E6%B2%BB%E7%90%86/22.2%20%E6%88%98%E7%95%A5%E7%AE%A1%E7%90%86.html","title":"22.2 战略管理","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第22章 组织通用治理/22.2 战略管理.md"}`),a={name:`22.2 战略管理.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_22-2-战略管理" tabindex="-1"><a class="header-anchor" href="#_22-2-战略管理"><span>22.2 战略管理</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>战略管理是指制定和实施组织战略，确保组织实现长期目标的过程。</p><h2 id="战略管理的核心内容" tabindex="-1"><a class="header-anchor" href="#战略管理的核心内容"><span>战略管理的核心内容</span></a></h2><h3 id="_1-战略制定" tabindex="-1"><a class="header-anchor" href="#_1-战略制定"><span>1. 战略制定</span></a></h3><ul><li><strong>定义</strong>：确定组织的战略方向和目标</li><li><strong>内容</strong>：环境分析、战略选择</li></ul><h3 id="_2-战略实施" tabindex="-1"><a class="header-anchor" href="#_2-战略实施"><span>2. 战略实施</span></a></h3><ul><li><strong>定义</strong>：执行战略计划</li><li><strong>内容</strong>：资源配置、组织调整</li></ul><h3 id="_3-战略评估" tabindex="-1"><a class="header-anchor" href="#_3-战略评估"><span>3. 战略评估</span></a></h3><ul><li><strong>定义</strong>：评估战略执行效果</li><li><strong>内容</strong>：绩效评估、战略调整</li></ul><h2 id="战略管理的流程" tabindex="-1"><a class="header-anchor" href="#战略管理的流程"><span>战略管理的流程</span></a></h2><h3 id="_1-战略分析" tabindex="-1"><a class="header-anchor" href="#_1-战略分析"><span>1. 战略分析</span></a></h3><ul><li><strong>内容</strong>：分析外部环境和内部能力</li><li><strong>方法</strong>：SWOT分析、PEST分析</li></ul><h3 id="_2-战略制定" tabindex="-1"><a class="header-anchor" href="#_2-战略制定"><span>2. 战略制定</span></a></h3><ul><li><strong>内容</strong>：确定战略目标和战略方案</li><li><strong>方法</strong>：战略选择矩阵</li></ul><h3 id="_3-战略实施" tabindex="-1"><a class="header-anchor" href="#_3-战略实施"><span>3. 战略实施</span></a></h3><ul><li><strong>内容</strong>：执行战略计划</li><li><strong>方法</strong>：项目管理、资源分配</li></ul><h3 id="_4-战略评估" tabindex="-1"><a class="header-anchor" href="#_4-战略评估"><span>4. 战略评估</span></a></h3><ul><li><strong>内容</strong>：评估战略效果</li><li><strong>方法</strong>：平衡计分卡、绩效指标</li></ul><h2 id="战略管理的方法" tabindex="-1"><a class="header-anchor" href="#战略管理的方法"><span>战略管理的方法</span></a></h2><h3 id="_1-swot分析" tabindex="-1"><a class="header-anchor" href="#_1-swot分析"><span>1. SWOT分析</span></a></h3><ul><li><strong>内容</strong>：分析优势、劣势、机会、威胁</li><li><strong>应用</strong>：战略定位</li></ul><h3 id="_2-pest分析" tabindex="-1"><a class="header-anchor" href="#_2-pest分析"><span>2. PEST分析</span></a></h3><ul><li><strong>内容</strong>：分析政治、经济、社会、技术因素</li><li><strong>应用</strong>：环境分析</li></ul><h3 id="_3-波特五力模型" tabindex="-1"><a class="header-anchor" href="#_3-波特五力模型"><span>3. 波特五力模型</span></a></h3><ul><li><strong>内容</strong>：分析行业竞争环境</li><li><strong>应用</strong>：竞争战略</li></ul><h2 id="战略管理的目标" tabindex="-1"><a class="header-anchor" href="#战略管理的目标"><span>战略管理的目标</span></a></h2><h3 id="_1-实现长期目标" tabindex="-1"><a class="header-anchor" href="#_1-实现长期目标"><span>1. 实现长期目标</span></a></h3><ul><li>确保组织长期发展</li><li>实现可持续增长</li></ul><h3 id="_2-增强竞争力" tabindex="-1"><a class="header-anchor" href="#_2-增强竞争力"><span>2. 增强竞争力</span></a></h3><ul><li>提高市场竞争力</li><li>占据有利地位</li></ul><h3 id="_3-优化资源配置" tabindex="-1"><a class="header-anchor" href="#_3-优化资源配置"><span>3. 优化资源配置</span></a></h3><ul><li>合理分配资源</li><li>提高资源利用率</li></ul><h2 id="战略管理的注意事项" tabindex="-1"><a class="header-anchor" href="#战略管理的注意事项"><span>战略管理的注意事项</span></a></h2><h3 id="_1-战略与执行结合" tabindex="-1"><a class="header-anchor" href="#_1-战略与执行结合"><span>1. 战略与执行结合</span></a></h3><ul><li>确保战略能够落地</li><li>避免战略与执行脱节</li></ul><h3 id="_2-动态调整" tabindex="-1"><a class="header-anchor" href="#_2-动态调整"><span>2. 动态调整</span></a></h3><ul><li>根据环境变化调整战略</li><li>保持战略灵活性</li></ul><h3 id="_3-全员参与" tabindex="-1"><a class="header-anchor" href="#_3-全员参与"><span>3. 全员参与</span></a></h3><ul><li>确保组织成员理解战略</li><li>共同推动战略实施</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>战略管理的流程</strong></li><li><strong>战略管理的方法</strong></li><li><strong>战略管理的目标</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>战略管理三步走，制定实施评估要做好，方法得当是关键</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：战略管理的第一步是什么？ A. 战略实施 B. 战略分析 C. 战略评估 D. 战略制定</p><p><strong>答案</strong>：B</p><p><strong>解析</strong>：战略管理的流程依次是：战略分析、战略制定、战略实施、战略评估。第一步是战略分析。</p>`,48)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};